-- Reconcile staging's independently-created catalogue UUIDs with the permanent
-- production UUIDs in data/player-catalogue.json. Preserve squads, results,
-- snapshots, aliases, prices, and inactive status while remapping references.
-- Reviewed source UUIDs trigger staging reconciliation. A populated database
-- without those UUIDs must match the reviewed catalogue before this is a no-op.

create temporary table _catalogue_clubs(id uuid primary key,name text not null,short_name text) on commit drop;
insert into _catalogue_clubs select id,name,short_name
from jsonb_to_recordset($json$[{"id":"24f4d5f3-7cb6-44f6-9531-530a44d1b27e","name":"Falkenbergs BTK","short_name":null},{"id":"340451e0-8b80-4746-9c76-3f7a9c4a4c9b","name":"BTK Rekord","short_name":null},{"id":"36804e63-fa5e-4525-a76c-a14fad17dd59","name":"Söderhamns UIF","short_name":null},{"id":"77f2d02c-715c-4bef-8ae1-f4cc101b2e93","name":"Eslövs AI BTK","short_name":null},{"id":"a68f7a5b-9b7c-4b4c-a9c3-1464110ffb34","name":"Halmstad BTK","short_name":null},{"id":"c4772637-315e-4745-8e17-61fbc4eefcb8","name":"Eskilstuna BTK","short_name":null},{"id":"ca863192-8330-4b9a-9459-54f993eda7a0","name":"Kosta SK","short_name":null},{"id":"d853b55e-a352-47b3-a8ff-209faabfb76b","name":"IFA Eskilstuna","short_name":null},{"id":"e63351d4-2c35-4697-9f8d-cebac4df085e","name":"Eskilstuna by STIGA","short_name":null},{"id":"f6d6d519-c925-47c3-9db8-3cbec544818d","name":"Spårvägens BTK","short_name":null}]$json$::jsonb) as x(id uuid,name text,short_name text);

create temporary table _catalogue_players(
 id uuid primary key,profixio_id text,stupa_user_role_id integer,club_id uuid,
 first_name text not null,last_name text not null,birth_year integer,ranking_position integer,
 ranking_points integer,price numeric(12,0) not null,active boolean not null,
 created_at timestamptz not null,source_updated_at timestamptz
) on commit drop;
insert into _catalogue_players
select id,profixio_id,stupa_user_role_id,club_id,first_name,last_name,birth_year,ranking_position,ranking_points,price,active,created_at,source_updated_at
