create temporary table _catalogue_reconciliation_control(should_apply boolean not null) on commit drop;
insert into _catalogue_reconciliation_control values (
 exists(select 1 from public.players p join _player_uuid_reconciliation m on m.source_id=p.id)
 or exists(select 1 from public.clubs c join _club_uuid_reconciliation m on m.source_id=c.id)
 or (not exists(select 1 from public.players) and not exists(select 1 from public.clubs))
);

do $preflight$
begin
 if not (select should_apply from _catalogue_reconciliation_control) then
  if (select count(*) from public.players)<>(select count(*) from _catalogue_players) or exists(
   select 1 from _catalogue_players e left join public.players a on a.id=e.id
   where a.id is null or a.profixio_id is distinct from e.profixio_id or a.stupa_user_role_id is distinct from e.stupa_user_role_id
    or a.club_id is distinct from e.club_id or a.first_name is distinct from e.first_name or a.last_name is distinct from e.last_name
    or a.birth_year is distinct from e.birth_year or a.ranking_position is distinct from e.ranking_position
    or a.ranking_points is distinct from e.ranking_points or a.price is distinct from e.price or a.active is distinct from e.active
  ) then raise exception 'Catalogue reconciliation stopped: populated player catalogue differs from the reviewed production snapshot.'; end if;
  if (select count(*) from public.clubs)<>(select count(*) from _catalogue_clubs) or exists(
   select 1 from _catalogue_clubs e left join public.clubs a on a.id=e.id
   where a.id is null or a.name is distinct from e.name or a.short_name is distinct from e.short_name
  ) then raise exception 'Catalogue reconciliation stopped: populated club catalogue differs from the reviewed production snapshot.'; end if;
  if exists(select 1 from _catalogue_identities e left join public.player_external_identities a
   on a.provider=e.provider and a.external_id=e.external_id
   where a.player_id is distinct from e.player_id or a.is_current is distinct from e.is_current)
  then raise exception 'Catalogue reconciliation stopped: populated identity map differs from the reviewed production snapshot.'; end if;
  return;
 end if;
 if exists(select 1 from public.players) or exists(select 1 from public.clubs) then
  if (select count(*) from public.players p join _player_uuid_reconciliation m on p.id=m.source_id)
     <>(select count(*) from _player_uuid_reconciliation)
   or (select count(*) from public.players)<>(select count(*) from _player_uuid_reconciliation)+2
   or not exists(select 1 from public.players where id='3060f824-568d-56c7-8a5c-7681f171f4a2'::uuid)
   or not exists(select 1 from public.players where id='9476ceee-ac94-52ce-a400-b3313ab7b737'::uuid)
  then raise exception 'Catalogue reconciliation stopped: staging player roster no longer matches the reviewed export.'; end if;
  if (select count(*) from public.clubs c join _club_uuid_reconciliation m on c.id=m.source_id)
     <>(select count(*) from _club_uuid_reconciliation)
   or (select count(*) from public.clubs)<>(select count(*) from _club_uuid_reconciliation)
  then raise exception 'Catalogue reconciliation stopped: staging clubs no longer match the reviewed export.'; end if;
 end if;
 if exists(select 1 from public.players p where p.id not in(select id from _catalogue_players) and p.id not in(select source_id from _player_uuid_reconciliation))
 then raise exception 'Catalogue reconciliation stopped: unexpected player UUIDs exist.'; end if;
 if exists(select 1 from public.clubs c where c.id not in(select id from _catalogue_clubs) and c.id not in(select source_id from _club_uuid_reconciliation))
 then raise exception 'Catalogue reconciliation stopped: unexpected club UUIDs exist.'; end if;
 if exists(select 1 from _player_uuid_reconciliation m join public.players p on p.id=m.source_id
  where p.profixio_id is distinct from m.profixio_id or p.first_name is distinct from m.first_name
   or p.last_name is distinct from m.last_name or p.birth_year is distinct from m.birth_year
   or p.club_id is distinct from m.club_source_id
   or p.ranking_position is distinct from m.ranking_position or p.ranking_points is distinct from m.ranking_points
   or p.price is distinct from m.price or p.active is distinct from m.active or p.stupa_user_role_id is not null)
 then raise exception 'Catalogue reconciliation stopped: a staging player differs from the reviewed identity map.'; end if;
 if exists(select 1 from _player_uuid_reconciliation m join public.players p on p.id=m.target_id join _catalogue_players c on c.id=m.target_id
  where p.first_name is distinct from c.first_name or p.last_name is distinct from c.last_name or p.profixio_id is distinct from c.profixio_id)
 then raise exception 'Catalogue reconciliation stopped: canonical player UUID belongs to another identity.'; end if;
 if exists(select 1 from _club_uuid_reconciliation m join public.clubs c on c.id=m.source_id where c.name is distinct from m.name)
 then raise exception 'Catalogue reconciliation stopped: staging club differs from reviewed name map.'; end if;
 if exists(select 1 from _catalogue_clubs e join public.clubs n on n.name=e.name and n.id<>e.id where n.id not in(select source_id from _club_uuid_reconciliation))
 then raise exception 'Catalogue reconciliation stopped: canonical club name belongs to an unexpected UUID.'; end if;
 if exists(select 1 from _catalogue_clubs e join public.clubs i on i.id=e.id where i.name is distinct from e.name)
 then raise exception 'Catalogue reconciliation stopped: canonical club UUID has a different name.'; end if;
end;
$preflight$;

-- Reserve canonical club UUIDs under temporary names, repoint foreign keys,
-- then remove legacy club rows and assign their permanent names.
do $clubs$
declare m record;
begin
 if not (select should_apply from _catalogue_reconciliation_control) then return; end if;
 for m in select * from _club_uuid_reconciliation loop
  if exists(select 1 from public.clubs where id=m.source_id) then
   if not exists(select 1 from public.clubs where id=m.target_id) then
    insert into public.clubs(id,name) values(m.target_id,'__catalogue_reconcile__'||m.target_id::text);
   end if;
   update public.players set club_id=m.target_id where club_id=m.source_id;
   update public.matches set home_club_id=m.target_id where home_club_id=m.source_id;
   update public.matches set away_club_id=m.target_id where away_club_id=m.source_id;
   update public.fantasy_team_gameweek_players set club_id_at_lock=m.target_id where club_id_at_lock=m.source_id;
   update public.player_gameweek_club_snapshots set club_id_at_lock=m.target_id where club_id_at_lock=m.source_id;
   delete from public.clubs where id=m.source_id;
  end if;
 end loop;
 insert into public.clubs(id,name,short_name) select id,name,short_name from _catalogue_clubs on conflict(id) do nothing;
 update public.clubs c set name=x.name,short_name=x.short_name from _catalogue_clubs x where c.id=x.id;
end;
$clubs$;

-- Release old unique license values before inserting canonical records. Identity
-- aliases stay linked to their source player until merge_player_records moves them.
update public.players p set profixio_id=null from _player_uuid_reconciliation m
where p.id=m.source_id and (select should_apply from _catalogue_reconciliation_control);
insert into public.players(id,profixio_id,stupa_user_role_id,club_id,first_name,last_name,birth_year,ranking_position,ranking_points,price,active,created_at,source_updated_at)
select id,profixio_id,stupa_user_role_id,club_id,first_name,last_name,birth_year,ranking_position,ranking_points,price,active,created_at,source_updated_at
from _catalogue_players where (select should_apply from _catalogue_reconciliation_control) on conflict(id) do nothing;

-- Changing a player UUID is not a squad transfer. An existing squad may
-- already have three players at a club after a real-world club move; the
-- normal selection trigger rejects even a same-club UUID replacement. Keep
-- every FK and uniqueness constraint active, and verify the club counts below.
create temporary table _squad_club_counts_before on commit drop as
select squad.fantasy_team_id,player.club_id,count(*)::integer as selected_count
from public.fantasy_team_players squad
join public.players player on player.id=squad.player_id
where (select should_apply from _catalogue_reconciliation_control)
group by squad.fantasy_team_id,player.club_id;

do $players$
declare m record;
begin
 if not (select should_apply from _catalogue_reconciliation_control) then return; end if;
 -- Keep both trigger changes in this one statement. If any merge fails, the
 -- statement rolls back the temporary trigger change as well.
 execute 'alter table public.fantasy_team_players disable trigger enforce_fantasy_team_club_limit';
 for m in select * from _player_uuid_reconciliation loop
  if exists(select 1 from public.players where id=m.source_id) then
   perform public.merge_player_records(m.target_id,m.source_id);
  end if;
 end loop;
 execute 'alter table public.fantasy_team_players enable trigger enforce_fantasy_team_club_limit';
end;
$players$;

do $verify_squads$
begin
 if not (select should_apply from _catalogue_reconciliation_control) then return; end if;
 if exists(
  select 1 from _squad_club_counts_before before_counts
  full join (
   select squad.fantasy_team_id,player.club_id,count(*)::integer as selected_count
   from public.fantasy_team_players squad
   join public.players player on player.id=squad.player_id
   group by squad.fantasy_team_id,player.club_id
  ) after_counts
   on after_counts.fantasy_team_id=before_counts.fantasy_team_id
    and after_counts.club_id is not distinct from before_counts.club_id
  where after_counts.selected_count is distinct from before_counts.selected_count
 ) then raise exception 'Catalogue reconciliation stopped: a fantasy squad club count changed.'; end if;
end;
$verify_squads$;

-- Match the remaining non-behavioral timestamps to the canonical player rows.
update public.players p set created_at=e.created_at,source_updated_at=e.source_updated_at
from _catalogue_players e where p.id=e.id and (select should_apply from _catalogue_reconciliation_control);

-- Restore the reviewed production identity map. Other staging-only aliases
-- remain attached to the canonical player as historical mappings.
update public.player_external_identities i set is_current=false
where i.player_id in(select id from _catalogue_players)
  and (select should_apply from _catalogue_reconciliation_control);
insert into public.player_external_identities(provider,external_id,player_id,is_current,first_seen_at,last_seen_at)
select provider,external_id,player_id,is_current,first_seen_at,last_seen_at from _catalogue_identities
where (select should_apply from _catalogue_reconciliation_control)
on conflict(provider,external_id) do update
set player_id=excluded.player_id,is_current=excluded.is_current,
 first_seen_at=least(public.player_external_identities.first_seen_at,excluded.first_seen_at),
 last_seen_at=greatest(public.player_external_identities.last_seen_at,excluded.last_seen_at);

do $verify$
begin
 if not (select should_apply from _catalogue_reconciliation_control) then return; end if;
 if (select count(*) from public.players)<>(select count(*) from _catalogue_players) or exists(
  select 1 from _catalogue_players e left join public.players a on a.id=e.id
  where a.id is null or a.profixio_id is distinct from e.profixio_id or a.stupa_user_role_id is distinct from e.stupa_user_role_id
   or a.club_id is distinct from e.club_id or a.first_name is distinct from e.first_name or a.last_name is distinct from e.last_name
   or a.birth_year is distinct from e.birth_year or a.ranking_position is distinct from e.ranking_position
   or a.ranking_points is distinct from e.ranking_points or a.price is distinct from e.price or a.active is distinct from e.active
   or a.created_at is distinct from e.created_at or a.source_updated_at is distinct from e.source_updated_at
 ) then raise exception 'Catalogue reconciliation verification failed: player rows differ.'; end if;
 if (select count(*) from public.clubs)<>(select count(*) from _catalogue_clubs) or exists(
  select 1 from _catalogue_clubs e left join public.clubs a on a.id=e.id
  where a.id is null or a.name is distinct from e.name or a.short_name is distinct from e.short_name
 ) then raise exception 'Catalogue reconciliation verification failed: club rows differ.'; end if;
 if exists(select 1 from _catalogue_identities e left join public.player_external_identities a
  on a.provider=e.provider and a.external_id=e.external_id
  where a.player_id is distinct from e.player_id or a.is_current is distinct from e.is_current)
 then raise exception 'Catalogue reconciliation verification failed: identity mapping differs.'; end if;
end;
$verify$;
